/**
 * Catalogue expansion. "core" items come from Axis Agro's established range (as listed on the
 * previous site); "enquiry" items are offered as sourcing enquiries only — never as guaranteed stock.
 */

const ENQUIRY_NOTE = "Sourcing enquiry: availability, volumes and specifications are assessed for each request and are not held as regular stock.";
const CORE_NOTE = "Specifications, volumes and seasonal availability are confirmed in writing for every enquiry.";

const DEFAULTS: Record<CategorySlug, Pick<Product, "packaging" | "logistics" | "grades">> = {
  fruits: { packaging: ["4–10kg cartons", "Palletised cartons", "Custom packaging on request"], logistics: ["Air freight for ripe or delicate fruit", "Reefer containers where transit allows"], grades: ["Size or count band agreed", "Class I / Class II", "Maturity stage agreed"] },
  vegetables: { packaging: ["Ventilated cartons", "Bunched or loose packing", "Custom packaging on request"], logistics: ["Air freight with cool-chain handling", "Reefer only for durable lines"], grades: ["Size or length grade agreed", "Fresh, firm and clean", "Residue testing on request"] },
  "roots-tubers": { packaging: ["Cartons", "Mesh or woven bags", "Custom packaging on request"], logistics: ["Air freight for perishable lines", "Ventilated or reefer containers for durable roots"], grades: ["Size or weight band agreed", "Sound, clean produce"] },
  "herbs-spices": { packaging: ["Cartons (fresh)", "Lined bags or cartons (dried)", "Custom packaging on request"], logistics: ["Air freight for fresh produce", "Sea or air freight for dried products"], grades: ["Moisture limit agreed (dried)", "Free from foreign matter", "Residue and microbiology testing on request"] },
  coffee: { packaging: ["60kg jute bags", "Jute bags with hermetic liners", "Bulk container liners"], logistics: ["FCL sea freight via Mombasa", "Samples by courier"], grades: ["Moisture typically ≤ 12.5%", "Defect count per contract", "Cup profile by sample where specified"] },
  cocoa: { packaging: ["Jute or sisal bags", "Bulk liners on request"], logistics: ["Sea freight in dry containers", "Moisture protection against condensation"], grades: ["Moisture commonly ≤ 7.5%", "Bean count per 100g agreed", "Cut-test limits per contract"] },
  oilseeds: { packaging: ["25kg or 50kg PP bags", "Paper bags", "Bulk bags"], logistics: ["FCL sea freight", "Fumigation as required"], grades: ["Purity and admixture to contract", "Moisture and oil content tested"] },
  "grains-pulses": { packaging: ["25kg or 50kg PP bags", "Bulk liner bags"], logistics: ["Sea freight in dry containers", "Fumigation as required"], grades: ["Moisture to safe storage level", "Foreign matter within contract limits", "Aflatoxin tested on request"] },
  nuts: { packaging: ["Vacuum-packed cartons (kernels)", "Jute or PP bags (in-shell)", "Drums (butters)"], logistics: ["Sea freight in dry containers", "Protect from heat and humidity"], grades: ["Moisture within specification", "Graded by size or style"] },
  "dried-products": { packaging: ["Food-grade lined cartons", "Bulk bags", "Retail packs on request"], logistics: ["Ambient sea or air freight", "Moisture-proof packaging"], grades: ["Moisture content agreed", "Additive-free options where specified"] },
};

type Spec = {
  slug: string;
  name: string;
  short: string;
  desc: [string, string];
  varieties: string[];
  image?: string;
  imageAlt?: string;
  icon?: IconName;
  botanical?: string;
  status?: "core" | "enquiry";
  grades?: string[];
  packaging?: string[];
  origins?: string[];
};

function group(group: CategorySlug, sub: string | undefined, kind: QuoteKind, icon: IconName, specs: Spec[]): Product[] {
  return specs.map((s) => {
    const status = s.status ?? "enquiry";
    const d = DEFAULTS[group];
    return {
      slug: s.slug,
      name: s.name,
      group,
      sub,
      status,
      kind,
      icon: s.icon ?? icon,
      image: s.image,
      imageAlt: s.imageAlt ?? s.name,
      short: s.short,
      description: s.desc,
      botanical: s.botanical,
      varieties: s.varieties,
      grades: s.grades ?? d.grades,
      origins: s.origins ?? ["Uganda"],
      originNote: "Sourced through partners in Uganda; origin and producer confirmed per consignment.",
      packaging: s.packaging ?? d.packaging,
      logistics: d.logistics,
      confirm: status === "core" ? CORE_NOTE : ENQUIRY_NOTE,
    };
  });
}

